with ins as (insert into public.artist_sound_tags (artist_slug,tag,source_url) select x.s,x.tag,x.u from json_to_recordset('[{"s":"jbabe","tag":"lo-fi, indie-pop mixed with rhythm and blues","u":"https://www.thewildcity.com/artists/13128-JBABE"}]'::json) as x(s text,tag text,u text) join public.artists a on a.slug=x.s on conflict (artist_slug,tag) do nothing returning 1) select count(*) from ins;